-- Stored procedures, functions, events and transactional patterns
CREATE PROCEDURE sp_touch_user(IN p_id BIGINT) UPDATE users SET updated_at = NOW() WHERE id = p_id;
CREATE OR REPLACE FUNCTION fn_double(x INT) RETURNS INT DETERMINISTIC RETURN x * 2;
CREATE FUNCTION IF NOT EXISTS fn_tax(amount DECIMAL(10, 2)) RETURNS DECIMAL(10, 2) DETERMINISTIC RETURN amount * 0.2;
DROP PROCEDURE IF EXISTS sp_touch_user;
DROP FUNCTION IF EXISTS fn_double;
CALL sp_touch_user(42);
CREATE EVENT IF NOT EXISTS ev_purge ON SCHEDULE EVERY 1 DAY STARTS '2025-01-01 03:00:00' DO DELETE FROM sessions WHERE expires_at < NOW();
DROP EVENT IF EXISTS ev_purge;
BEGIN;
ROLLBACK;
SAVEPOINT sp1;
ROLLBACK TO SAVEPOINT sp1;
RELEASE SAVEPOINT sp1;
SET autocommit = 0;
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
START TRANSACTION READ ONLY;
START TRANSACTION WITH CONSISTENT SNAPSHOT;
XA START 'x1';
CREATE DEFINER = 'root'@'localhost' PROCEDURE sp_purge() DELETE FROM sessions WHERE expires_at < NOW();
